import fs from 'node:fs';
import { execFileSync } from 'node:child_process';
const DEV='https://d21fbe6u80.execute-api.us-east-1.amazonaws.com/dev';
const PROD='https://je3zud66nb.execute-api.us-east-1.amazonaws.com/prod-v2';
const REGION='us-east-1';
const OUT='radio/docs/diagnostics/ATTEMPT2_VEC_RECONCILE.json';
const F={dev:'stashbox-radio-api-dev-v2',prod:'stashbox-radio-api-prod-v2'};
fs.mkdirSync('radio/docs/diagnostics',{recursive:true});
function token(fn){const j=JSON.parse(execFileSync('aws',['lambda','get-function-configuration','--function-name',fn,'--region',REGION,'--output','json'],{encoding:'utf8'}));const v=j?.Environment?.Variables||{};const t=String(v.ADMIN_TOKEN||v.RADIO_ADMIN_TOKEN||'').trim();if(!t)throw new Error(`missing token ${fn}`);return t;}
async function req(url,{method='GET',token='',body}={}){const h={Accept:'application/json'};if(token)h['x-admin-token']=token;if(body!==undefined)h['Content-Type']='application/json';const r=await fetch(url,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});const tx=await r.text();let b={};try{b=tx?JSON.parse(tx):{};}catch{b={raw:tx};}if(!r.ok)throw new Error(`${method} ${url} -> ${r.status}: ${b.error||b.message||tx.slice(0,250)}`);return b;}
const list=(b,k)=>Array.isArray(b)?b:(b?.[k]||b?.items||b?.data||[]);const sk=s=>String(s?.song_key||s?.songKey||'').trim();const fid=f=>String(f?.folder_slug||f?.folder_name||'').trim().toLowerCase();const aid=a=>String(a?.id||a?.asset_id||'').trim();const aurl=a=>String(a?.public_url||a?.url||'').trim();
function keyFrom(a){const explicit=String(a?.s3_key||a?.key||'').trim();if(explicit)return explicit;const u=aurl(a);try{const x=new URL(u);return decodeURIComponent(x.pathname.replace(/^\//,''));}catch{return'';}}
function mediaId(a){return keyFrom(a)||aurl(a);}
function folderPayload(f,status=f.status||'active'){return{folder_name:f.folder_name||'',folder_type:f.folder_type||'general',description:f.description||'',status,priority:f.priority||'medium',notes:f.notes||'',relevant_artists:Array.isArray(f.relevant_artists)?f.relevant_artists:[],relevant_genres:Array.isArray(f.relevant_genres)?f.relevant_genres:[],relevant_moods:Array.isArray(f.relevant_moods)?f.relevant_moods:[],relevant_songs:Array.isArray(f.relevant_songs)?f.relevant_songs:[]};}
function assetPayload(a,folderId){const k=keyFrom(a);return{...a,id:aid(a),folder_id:folderId,asset_type:a.asset_type||a.type||'image',file_name:a.file_name||a.filename||k.split('/').pop()||'',s3_key:k,public_url:aurl(a),thumbnail_url:a.thumbnail_url||a.thumbnailUrl||aurl(a),content_type:a.content_type||a.contentType||'',ratio_label:a.ratio_label||'',caption:a.caption||'',alt_text:a.alt_text||a.altText||'',notes:a.notes||''};}
function directPayload(song,a){return{song_key:song,asset_type:a.asset_type||a.type||'image',file_name:a.file_name||a.filename||'',s3_key:keyFrom(a),public_url:aurl(a),thumbnail_url:a.thumbnail_url||a.thumbnailUrl||aurl(a),content_type:a.content_type||'',size_bytes:a.size_bytes||null,width:a.width||null,height:a.height||null,ratio_label:a.ratio_label||'',caption:a.caption||'',alt_text:a.alt_text||'',notes:a.notes||''};}
function deep(v,fm,am){if(Array.isArray(v))return v.map(x=>deep(x,fm,am));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,(k==='folder_id'||k==='folderId')&&typeof x==='string'&&fm.has(x)?fm.get(x):deep(x,fm,am)]));if(typeof v==='string'){if(fm.has(v))return fm.get(v);if(am.has(v))return am.get(v);}return v;}
const recipe=b=>!b||b.found===false?null:(b.recipe||b.data?.recipe||null);
const report={started_at:new Date().toISOString(),folders:{created:0,updated:0,hidden_extra:0},folder_assets:{created:0,reused:0,hidden_extra:0},direct:{created:0,reused:0,hidden_extra:0},recipes:0,settings:0,failures:[],verification:{},fatal_error:null};
try{const dt=token(F.dev),pt=token(F.prod);const devFolders=list(await req(`${DEV}/radio/admin/visuals/folders`,{token:dt}),'folders');let prodFolders=list(await req(`${PROD}/radio/admin/visuals/folders`,{token:pt}),'folders');const devIds=new Set(devFolders.map(fid));const pfBy=new Map(prodFolders.map(f=>[fid(f),f]));const fm=new Map(),am=new Map();
 for(const pf of prodFolders){if(!devIds.has(fid(pf))&&String(pf.status||'active').toLowerCase()==='active'){try{await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(String(pf.id))}`,{method:'PUT',token:pt,body:folderPayload(pf,'hidden')});report.folders.hidden_extra++;}catch(e){report.failures.push({stage:'hide-extra-folder',folder:fid(pf),error:e.message});}}}
 for(const df of devFolders){const did=String(df.id||'');if(!did)continue;let pf=pfBy.get(fid(df));try{if(!pf){const c=await req(`${PROD}/radio/admin/visuals/folders`,{method:'POST',token:pt,body:folderPayload(df,'active')});pf=c.folder||c.data?.folder||c.data||c;report.folders.created++;}else{const u=await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(String(pf.id))}`,{method:'PUT',token:pt,body:folderPayload(df,'active')});pf=u.folder||pf;report.folders.updated++;}const pid=String(pf.id||'');fm.set(did,pid);const da=list(await req(`${DEV}/radio/admin/visuals/folders/${encodeURIComponent(did)}/assets`,{token:dt}),'assets');let pa=list(await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(pid)}/assets`,{token:pt}),'assets');const byId=new Map(pa.map(a=>[aid(a),a]).filter(([x])=>x)),byMedia=new Map(pa.map(a=>[mediaId(a),a]).filter(([x])=>x));const wanted=new Set();for(const a of da){const id=aid(a),mid=mediaId(a);wanted.add(mid);let q=byId.get(id)||byMedia.get(mid);if(q){am.set(id,aid(q));report.folder_assets.reused++;continue;}const p=assetPayload(a,pid);if(!p.s3_key)throw new Error(`Cannot derive s3_key for ${mid}`);const c=await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(pid)}/assets`,{method:'POST',token:pt,body:p});q=c.asset||c.data?.asset||c.data||c;am.set(id,aid(q)||id);report.folder_assets.created++;}pa=list(await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(pid)}/assets`,{token:pt}),'assets');for(const a of pa){if(wanted.has(mediaId(a)))continue;await req(`${PROD}/radio/admin/visuals/folders/${encodeURIComponent(pid)}/assets/${encodeURIComponent(aid(a))}`,{method:'DELETE',token:pt});report.folder_assets.hidden_extra++;}}
 catch(e){report.failures.push({stage:'folder',folder:fid(df),error:e.message});}}
 const songs=list(await req(`${DEV}/admin/songs`,{token:dt}),'songs');for(const s of songs){const key=sk(s);if(!key)continue;const enc=encodeURIComponent(key);try{const dd=list(await req(`${DEV}/radio/admin/vec/song-assets?song_key=${enc}`,{token:dt}),'assets');let pd=list(await req(`${PROD}/radio/admin/vec/song-assets?song_key=${enc}`,{token:pt}),'assets');const byMedia=new Map(pd.map(a=>[mediaId(a),a]).filter(([x])=>x));const wanted=new Set();for(const a of dd){const id=aid(a),mid=mediaId(a);wanted.add(mid);let q=byMedia.get(mid);if(q){am.set(id,aid(q));report.direct.reused++;continue;}const c=await req(`${PROD}/radio/admin/vec/song-assets`,{method:'POST',token:pt,body:directPayload(key,a)});q=c.asset||c.data?.asset||c.data||c;am.set(id,aid(q));report.direct.created++;}pd=list(await req(`${PROD}/radio/admin/vec/song-assets?song_key=${enc}`,{token:pt}),'assets');for(const a of pd){if(wanted.has(mediaId(a)))continue;await req(`${PROD}/radio/admin/vec/song-assets/${encodeURIComponent(aid(a))}`,{method:'DELETE',token:pt});report.direct.hidden_extra++;}const dr=recipe(await req(`${DEV}/radio/vec/recipe?song_key=${enc}`));if(dr){await req(`${PROD}/radio/admin/vec/recipe`,{method:'PUT',token:pt,body:{song_key:key,recipe:deep(dr,fm,am)}});report.recipes++;}let ds=null;try{ds=await req(`${DEV}/radio/admin/songs/${enc}/visual-settings`,{token:dt});}catch{}if(ds){await req(`${PROD}/radio/admin/songs/${enc}/visual-settings`,{method:'PUT',token:pt,body:{order_mode:ds.order_mode,folder_mappings:deep(ds.folder_mappings||[],fm,am),asset_mappings:deep(ds.asset_mappings||[],fm,am)}});report.settings++;}}
 catch(e){report.failures.push({stage:'song',song_key:key,error:e.message});}}
 report.verification={folder_map:fm.size,asset_map:am.size};
}catch(e){report.fatal_error=e?.stack||e?.message||String(e);}finally{report.finished_at=new Date().toISOString();report.ok=!report.fatal_error&&report.failures.length===0;fs.writeFileSync(OUT,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));}if(!report.ok)process.exit(2);
